def transform(grid):
    # Recolor the two palette values in ascending order to 0 and 2.
    colors = sorted({v for row in grid for v in row})
    if len(colors) == 1:
        return [[0 if v == colors[0] else v for v in row] for row in grid]
    mapping = {colors[0]: 0, colors[1]: 2}
    return [[mapping[v] for v in row] for row in grid]
